  'about.hero.eyebrow'     : { es:'Fundador · Palferia.me · Valencia',    en:'Founder · Palferia.me · Valencia',     va:'Fundador · Palferia.me · València'    },
  'about.hero.role'        : { es:'Sport Business · <span class="hl">Agentes IA</span> · Patrocinios', en:'Sport Business · <span class="hl">AI Agents</span> · Sponsorships', va:'Sport Business · <span class="hl">Agents IA</span> · Patrocinis' },
  'about.hero.manifesto'   : { es:'Empecé a correr en 2016 sin saber que eso me iba a cambiar la forma de ver los negocios.<br><br>Desde entonces, <strong>el deporte es mi mecanismo</strong> — y el trabajo invisible detrás de cada evento, academia o club es lo que me apasiona resolver.', en:'I started running in 2016 without knowing it would change the way I see business.<br><br>Since then, <strong>sport has been my mechanism</strong> — and the invisible work behind every event, academy or club is what I\'m passionate about solving.', va:'Vaig començar a córrer el 2016 sense saber que açò em canviaria la manera de veure els negocis.<br><br>Des d\'aleshores, <strong>l\'esport és el meu mecanisme</strong> — i el treball invisible darrere de cada event, acadèmia o club és el que m\'apassiona resoldre.' },
