  'lp.ac.auto4.li2'        : { es:'Informe mensual: tasa de retención, cobros, bajas y tendencias', en:'Monthly report: retention rate, payments, drop-outs and trends', va:'Informe mensual: taxa de retenció, cobraments, baixes i tendències' },
