  'lp.ac.tier.h2'          : { es:'Tres niveles.<br><span class="hl">Un sistema.</span><br>Elige el tuyo.', en:'Three levels.<br><span class="hl">One system.</span><br>Choose yours.', va:'Tres nivells.<br><span class="hl">Un sistema.</span><br>Tria el teu.' },
  'lp.ac.tier.sub'         : { es:'El agente que configuramos para tu academia depende de lo que necesitas automatizar ahora mismo. Puedes empezar en Alevines y evolucionar cuando tenga sentido.', en:'The agent we configure for your academy depends on what you need to automate right now. You can start at Alevines and evolve when it makes sense.', va:'L\'agent que configurem per a la teua acadèmia depèn del que necessites automatitzar ara mateix. Pots començar a Alevins i evolucionar quan tinga sentit.' },
