  'lp.ac.tier2.limit'      : { es:'Optimización bimensual por revisión de logs programada. No incluye llamadas periódicas de revisión.', en:'Bimonthly optimisation by scheduled log review. Does not include periodic review calls.', va:'Optimització bimensual per revisió de logs programada. No inclou trucades periòdiques de revisió.' },
