  'lp.cl.tier3.cta'        : { es:'Lidera la primera división →', en:'Lead the top division →', va:'Lidera la primera divisió →' },
  'lp.cl.impl.h2'          : { es:'Activo en<br><span class="hl">3 semanas.</span><br>Sin cambiar<br>tu software.', en:'Live in<br><span class="hl">3 weeks.</span><br>Without changing<br>your software.', va:'Actiu en<br><span class="hl">3 setmanes.</span><br>Sense canviar<br>el teu programari.' },
  'lp.cl.impl.sub'         : { es:'El Club Agent se integra sobre lo que ya usas. Clupik sigue gestionando tu club — el agente añade la capa de comunicación e inteligencia que falta.', en:'The Club Agent integrates with what you already use. Clupik keeps managing your club — the agent adds the communication and intelligence layer that\'s missing.', va:'El Club Agent s\'integra sobre el que ja uses. Clupik continua gestionant el teu club — l\'agent afegeix la capa de comunicació i intel·ligència que falta.' },
  'lp.cl.step1.name'       : { es:'Diagnóstico', en:'Diagnosis', va:'Diagnòstic' },
  'lp.cl.step1.desc'       : { es:'Auditamos el stack actual del club, los canales de comunicación y los flujos de captación. Identificamos cuántos leads se pierden cada temporada y dónde está el mayor impacto de automatizar.', en:'We audit the club\'s current stack, communication channels and acquisition flows. We identify how many leads are lost each season and where automation has the greatest impact.', va:'Auditem el stack actual del club, els canals de comunicació i els fluxos de captació. Identifiquem quants leads es perden cada temporada i on hi ha el major impacte d\'automatitzar.' },
  'lp.cl.step2.name'       : { es:'Diseño del agente', en:'Agent design', va:'Disseny de l\'agent' },
  'lp.cl.step2.desc'       : { es:'Configuramos el agente con las categorías, precios, documentación y preguntas frecuentes específicas de tu club. Habla como vosotros, con los datos exactos de vuestra estructura deportiva.', en:'We configure the agent with your club\'s specific categories, prices, documentation and FAQs. It speaks like you do, with the exact data of your sporting structure.', va:'Configurem l\'agent amb les categories, preus, documentació i preguntes freqüents específiques del teu club. Parla com vosaltres, amb les dades exactes de la vostra estructura esportiva.' },
  'lp.cl.step3.name'       : { es:'Integración', en:'Integration', va:'Integració' },
  'lp.cl.step3.desc'       : { es:'Conectamos el agente a Clupik/Spond, WhatsApp Business y vuestro canal web. Construimos los 4 bloques de automatización y los probamos con casos reales antes de activar.', en:'We connect the agent to Clupik/Spond, WhatsApp Business and your web channel. We build the 4 automation blocks and test them with real cases before going live.', va:'Connectem l\'agent a Clupik/Spond, WhatsApp Business i el vostre canal web. Construïm els 4 blocs d\'automatització i els provem amb casos reals abans d\'activar.' },
  'lp.cl.step4.name'       : { es:'Activación', en:'Activation', va:'Activació' },
  'lp.cl.step4.desc'       : { es:'Go live con acompañamiento la primera semana. Formamos al coordinador y la directiva para que operen el sistema.', en:'Go live with support during the first week. We train the coordinator and board to operate the system.', va:'Go live amb acompanyament la primera setmana. Formem el coordinador i la directiva perquè operen el sistema.' },
  'lp.cl.mant.h2'          : { es:'El sistema<br><span class="hl">sigue rodando.</span><br>Tú te centras<br>en el club.', en:'The system<br><span class="hl">keeps running.</span><br>You focus<br>on the club.', va:'El sistema<br><span class="hl">segueix rodant.</span><br>Tu et centres<br>en el club.' },
  'lp.cl.mant.sub'         : { es:'El mantenimiento corrige y optimiza lo que ya funciona. Cada plan tiene un alcance definido. Lo que no esté incluido expresamente se presupuesta aparte.', en:'Maintenance corrects and optimises what already works. Each plan has a defined scope. Anything not expressly included is quoted separately.', va:'El manteniment corregeix i optimitza el que ja funciona. Cada pla té un abast definit. El que no estiga inclòs expressament es pressuposta a part.' },
