  'lp.cl.plan1.name'       : { es:'Mantenimiento Esencial', en:'Essential Maintenance', va:'Manteniment Essencial' },
  'lp.cl.plan1.desc'       : { es:'El sistema sigue activo. Supervisión básica, corrección de errores y una revisión mensual para que nada se detenga sin que la directiva lo note.', en:'The system stays active. Basic monitoring, error correction and a monthly review so nothing stops without the board noticing.', va:'El sistema segueix actiu. Supervisió bàsica, correcció d\'errors i una revisió mensual perquè res es detinga sense que la directiva ho note.' },
