  'lp.cl.plan1.limit'      : { es:'Atención directa a familias o socios, nuevas automatizaciones, cambios de lógica, formación al equipo del club, soporte fuera de horario laboral ni consumos de plataformas externas.', en:'Direct support for families or members, new automations, logic changes, club team training, support outside business hours or external platform costs.', va:'Atenció directa a famílies o socis, noves automatitzacions, canvis de lògica, formació a l\'equip del club, suport fora d\'horari laboral ni consums de plataformes externes.' },
