  'lp.cl.plan2.li6'        : { es:'Detección de preguntas frecuentes no cubiertas y actualización del agente', en:'Detection of unanswered FAQs and agent update', va:'Detecció de preguntes freqüents no cobertes i actualització de l\'agent' },
