  'lp.cl.plan2.limit'      : { es:'Nuevos canales, nuevas integraciones, rediseño del agente, nuevas automatizaciones, formación recurrente al equipo ni soporte fuera de horario laboral.', en:'New channels, new integrations, agent redesign, new automations, recurring team training or support outside business hours.', va:'Nous canals, noves integracions, redisseny de l\'agent, noves automatitzacions, formació recurrent a l\'equip ni suport fora d\'horari laboral.' },
