  'lp.cl.plan3.li5'        : { es:'Informe avanzado con métricas de renovación, impagos recuperados y altas por sección', en:'Advanced report with renewal metrics, recovered non-payments and registrations by section', va:'Informe avançat amb mètriques de renovació, impagaments recuperats i altes per secció' },
  'lp.cl.plan3.li6'        : { es:'Plan de contingencia documentado ante fallos críticos en temporada', en:'Documented contingency plan for critical failures during the season', va:'Pla de contingència documentat davant fallades crítiques en temporada' },
