  'lp.ev.plan1.badge'      : { es:'Pit Stop', en:'Pit Stop', va:'Pit Stop' },
  'lp.ev.plan1.name'       : { es:'Mantenimiento Esencial', en:'Essential Maintenance', va:'Manteniment Essencial' },
  'lp.ev.plan1.desc'       : { es:'El sistema sigue activo entre eventos. Supervisión básica, corrección de errores y una revisión mensual para que nada falle cuando abres inscripciones.', en:'The system stays active between events. Basic monitoring, error correction and a monthly review so nothing fails when you open registrations.', va:'El sistema segueix actiu entre esdeveniments. Supervisió bàsica, correcció d\'errors i una revisió mensual perquè res falle quan obres les inscripcions.' },
