  'lp.ev.plan1.li4'        : { es:'Revisión mensual de conversaciones — consultas e interesados del evento', en:'Monthly conversation review — event enquiries and prospects', va:'Revisió mensual de converses — consultes i interessats de l\'esdeveniment' },
