  'lp.fed.tier2.name'     : { es:'Fed Pro', en:'Fed Pro', va:'Fed Pro' },
  'lp.fed.tier2.desc'     : { es:'Sistema completo de atención, tramitación, comunicación y gestión de competiciones. La federación opera al doble de capacidad con el mismo equipo humano.', en:'Complete system for support, processing, communication and competition management. The federation operates at twice the capacity with the same human team.', va:'Sistema complet d\'atenció, tramitació, comunicació i gestió de competicions. La federació opera al doble de capacitat amb el mateix equip humà.' },
  'lp.fed.tier2.li1'      : { es:'Todo lo del Fed Starter incluido', en:'Everything in Fed Starter included', va:'Tot el del Fed Starter inclòs' },
  'lp.fed.tier2.li2'      : { es:'Gestión automatizada del ciclo completo de competiciones', en:'Automated management of the full competition cycle', va:'Gestió automatitzada del cicle complet de competicions' },
  'lp.fed.tier2.li3'      : { es:'Comunicación segmentada por modalidad y zona geográfica', en:'Communication segmented by discipline and geographic area', va:'Comunicació segmentada per modalitat i zona geogràfica' },
  'lp.fed.tier2.li4'      : { es:'Alertas de clubs en riesgo de baja o sin actividad', en:'Alerts for clubs at risk of dropping out or inactive', va:'Alertes de clubs en risc de baixa o sense activitat' },
