  'lp.fed.tier3.note'     : { es:'Proyecto personalizado', en:'Custom project', va:'Projecte personalitzat' },
  'lp.fed.tier3.desc'     : { es:'Para federaciones con múltiples delegaciones territoriales, varias modalidades y necesidad de coordinación con federación nacional y organismos autonómicos.', en:'For federations with multiple territorial delegations, several disciplines and the need to coordinate with the national federation and regional bodies.', va:'Per a federacions amb múltiples delegacions territorials, diverses modalitats i necessitat de coordinació amb la federació nacional i organismes autonòmics.' },
