  'lp.fed.tier3.li3'      : { es:'Integración con plataformas autonómicas y nacionales', en:'Integration with regional and national platforms', va:'Integració amb plataformes autonòmiques i nacionals' },
  'lp.fed.tier3.li4'      : { es:'Gestión unificada de licencias inter-delegación', en:'Unified cross-delegation licence management', va:'Gestió unificada de llicències inter-delegació' },
