  'lp.tur.plan2.name'     : { es:'Mantenimiento + Temporada', en:'Maintenance + Season', va:'Manteniment + Temporada' },
  'lp.tur.plan2.desc'     : { es:'El agente mejora mes a mes y está reforzado en temporada alta — cuando más consultas entran y más se juega cada reserva directa frente a las OTAs.', en:'The agent improves month by month and is reinforced in high season — when most queries come in and each direct booking matters most against OTAs.', va:'L\'agent millora mes a mes i està reforçat en temporada alta — quan més consultes entren i més es juga cada reserva directa davant les OTAs.' },
  'lp.tur.plan2.li1'      : { es:'Todo lo del plan Pit Stop', en:'Everything in the Pit Stop plan', va:'Tot el del pla Pit Stop' },
  'lp.tur.plan2.li2'      : { es:'Hasta 3h/mes de ajustes incluidas', en:'Up to 3h/month of adjustments included', va:'Fins a 3h/mes d\'ajustos incloses' },
  'lp.tur.plan2.li3'      : { es:'Supervisión prioritaria en temporada alta (verano, Semana Santa, navidades)', en:'Priority monitoring in high season (summer, Easter, Christmas)', va:'Supervisió prioritària en temporada alta (estiu, Setmana Santa, nadals)' },
