  'lp.sp.tier2.desc'      : { es:'Sistema completo de prospección, gestión de propuestas, relación con patrocinadores activos y reporting de ROI. Cada acuerdo activo recibe su informe mensual automático.', en:'Complete system for prospecting, proposal management, active sponsor relationships and ROI reporting. Every active deal receives its automatic monthly report.', va:'Sistema complet de prospecció, gestió de propostes, relació amb patrocinadors actius i reporting de ROI. Cada acord actiu rep el seu informe mensual automàtic.' },
  'lp.sp.tier2.li1'       : { es:'Todo lo del Sponsor Starter incluido', en:'Everything in Sponsor Starter included', va:'Tot el del Sponsor Starter inclòs' },
  'lp.sp.tier2.li2'       : { es:'Gestión de relación con patrocinadores activos (actualizaciones mensuales)', en:'Active sponsor relationship management (monthly updates)', va:'Gestió de relació amb patrocinadors actius (actualitzacions mensuals)' },
  'lp.sp.tier2.li3'       : { es:'Reporting automático de ROI por patrocinador', en:'Automatic ROI reporting per sponsor', va:'Reporting automàtic de ROI per patrocinador' },
