  'lp.sp.tier2.li5'       : { es:'Dossier anual de impacto para cada patrocinador', en:'Annual impact dossier for each sponsor', va:'Dossier anual d\'impacte per a cada patrocinador' },
  'lp.sp.tier2.li6'       : { es:'Optimización mensual de secuencias de prospección', en:'Monthly optimisation of prospecting sequences', va:'Optimització mensual de seqüències de prospecció' },
