  'lp.sp.tier3.desc'      : { es:'Para organizaciones con múltiples propiedades deportivas (varias entidades, eventos o equipos) que necesitan gestionar un portfolio de patrocinadores de forma centralizada.', en:'For organisations with multiple sports properties (various entities, events or teams) that need to manage a sponsorship portfolio centrally.', va:'Per a organitzacions amb múltiples propietats esportives (diverses entitats, events o equips) que necessiten gestionar un portfolio de patrocinadors de forma centralitzada.' },
