  'lp.sp.mant.h2'         : { es:'El pipeline<br><span class="hl">siempre activo.</span><br>Los acuerdos,<br>siempre informados.', en:'The pipeline<br><span class="hl">always active.</span><br>Deals,<br>always informed.', va:'El pipeline<br><span class="hl">sempre actiu.</span><br>Els acords,<br>sempre informats.' },
  'lp.sp.mant.sub'        : { es:'Los dossieres se quedan obsoletos, las APIs de CRM se actualizan y las secuencias de seguimiento necesitan ajuste cuando cambian los resultados. El mantenimiento mantiene el sistema operativo sin que tengas que gestionarlo. Lo que no esté incluido expresamente se presupuesta aparte.', en:'Dossiers become obsolete, CRM APIs update and follow-up sequences need adjustment when results change. Maintenance keeps the system operational without you having to manage it. Anything not expressly included is quoted separately.', va:'Els dossiers queden obsolets, les APIs de CRM s\'actualitzen i les seqüències de seguiment necessiten ajust quan canvien els resultats. El manteniment manté el sistema operatiu sense que hages de gestionar-ho. El que no estiga inclòs expressament es pressuposta a part.' },
  'lp.sp.plan1.badge'     : { es:'Pit Stop', en:'Pit Stop', va:'Pit Stop' },
  'lp.sp.plan1.name'      : { es:'Mantenimiento Esencial', en:'Essential Maintenance', va:'Manteniment Essencial' },
  'lp.sp.plan1.desc'      : { es:'El sistema de prospección sigue funcionando. Supervisión básica, corrección de errores y actualización del dossier y los materiales de prospección cuando cambian los objetivos de la entidad.', en:'The prospecting system keeps working. Basic monitoring, error correction and update of the dossier and prospecting materials when the entity\'s objectives change.', va:'El sistema de prospecció continua funcionant. Supervisió bàsica, correcció d\'errors i actualització del dossier i els materials de prospecció quan canvien els objectius de l\'entitat.' },
  'lp.sp.plan1.li1'       : { es:'Supervisión del sistema y detección de fallos', en:'System monitoring and fault detection', va:'Supervisió del sistema i detecció de fallades' },
  'lp.sp.plan1.li2'       : { es:'Corrección de errores y restauración del servicio', en:'Error correction and service restoration', va:'Correcció d\'errors i restauració del servei' },
