  'lp.sp.plan1.li4'       : { es:'Actualización de plantillas de dossier y materiales de prospección cuando cambian los objetivos', en:'Update of dossier templates and prospecting materials when objectives change', va:'Actualització de plantilles de dossier i materials de prospecció quan canvien els objectius' },
  'lp.sp.plan1.li5'       : { es:'Revisión mensual de secuencias activas — propuestas sin respuesta y seguimientos caídos', en:'Monthly review of active sequences — unanswered proposals and dropped follow-ups', va:'Revisió mensual de seqüències actives — propostes sense resposta i seguiments caiguts' },
