  'lp.sp.plan1.limit'     : { es:'Gestión directa con marcas, nuevas automatizaciones, nuevas integraciones, soporte fuera de horario laboral ni consumos de plataformas externas.', en:'Direct brand management, new automations, new integrations, out-of-hours support or external platform costs.', va:'Gestió directa amb marques, noves automatitzacions, noves integracions, suport fora d\'horari laboral ni consums de plataformes externes.' },
  'lp.sp.plan1.cta'       : { es:'Reservar reunión', en:'Book a meeting', va:'Reservar reunió' },
