  'lp.sp.plan2.name'      : { es:'Mantenimiento + Ciclo', en:'Maintenance + Cycle', va:'Manteniment + Cicle' },
  'lp.sp.plan2.desc'      : { es:'El sistema mejora mes a mes y está reforzado en los momentos críticos del ciclo de patrocinio — los 90 días previos a la renovación de cada acuerdo activo.', en:'The system improves month by month and is reinforced at the critical moments of the sponsorship cycle — the 90 days before each active deal\'s renewal.', va:'El sistema millora mes a mes i està reforçat en els moments crítics del cicle de patrocini — els 90 dies previs a la renovació de cada acord actiu.' },
  'lp.sp.plan2.li1'       : { es:'Todo lo del plan Pit Stop', en:'Everything in the Pit Stop plan', va:'Tot el del pla Pit Stop' },
  'lp.sp.plan2.li2'       : { es:'Hasta 3h/mes de ajustes incluidas', en:'Up to 3h/month of adjustments included', va:'Fins a 3h/mes d\'ajustos incloses' },
  'lp.sp.plan2.li3'       : { es:'Supervisión prioritaria en los 90 días previos a la renovación de acuerdos activos', en:'Priority monitoring in the 90 days before active deal renewals', va:'Supervisió prioritària en els 90 dies previs a la renovació d\'acords actius' },
  'lp.sp.plan2.li4'       : { es:'Revisión quincenal de las secuencias de prospección — propuestas sin respuesta y follow-ups caídos', en:'Fortnightly review of prospecting sequences — unanswered proposals and dropped follow-ups', va:'Revisió quinzenal de les seqüències de prospecció — propostes sense resposta i follow-ups caiguts' },
  'lp.sp.plan2.li5'       : { es:'Optimización del dossier basada en las conversiones reales del período anterior', en:'Dossier optimisation based on actual conversions from the previous period', va:'Optimització del dossier basada en les conversions reals del període anterior' },
  'lp.sp.plan2.li6'       : { es:'Detección de marcas con interés sin avance y ajuste de secuencia', en:'Detection of brands with interest but no progress and sequence adjustment', va:'Detecció de marques amb interès sense avenç i ajust de seqüència' },
  'lp.sp.plan2.li7'       : { es:'Soporte técnico por tickets en horario laboral', en:'Technical support via tickets during business hours', va:'Suport tècnic per tickets en horari laboral' },
  'lp.sp.plan2.li8'       : { es:'Informe mensual con métricas de pipeline y conversión', en:'Monthly report with pipeline and conversion metrics', va:'Informe mensual amb mètriques de pipeline i conversió' },
  'lp.sp.plan2.limit'     : { es:'Rediseño completo del agente, nuevas integraciones, negociación directa con marcas, soporte fuera de horario laboral ni consumos de plataformas externas.', en:'Full agent redesign, new integrations, direct brand negotiation, out-of-hours support or external platform costs.', va:'Redisseny complet de l\'agent, noves integracions, negociació directa amb marques, suport fora d\'horari laboral ni consums de plataformes externes.' },
  'lp.sp.plan2.cta'       : { es:'Reservar reunión', en:'Book a meeting', va:'Reservar reunió' },
