  'lp.sp.plan3.name'      : { es:'Gestión Continua', en:'Continuous Management', va:'Gestió Contínua' },
  'lp.sp.plan3.val'       : { es:'Según<br>proyecto', en:'By<br>project', va:'Segons<br>projecte' },
  'lp.sp.plan3.note'      : { es:'Definido en contrato', en:'Defined in contract', va:'Definit en contracte' },
  'lp.sp.plan3.desc'      : { es:'Para entidades con un portfolio de patrocinadores activos y varias propiedades. El agente evoluciona cada temporada y el reporting avanzado cierra renovaciones con datos reales.', en:'For entities with an active sponsor portfolio and several properties. The agent evolves every season and the advanced reporting closes renewals with real data.', va:'Per a entitats amb un portfolio de patrocinadors actius i diverses propietats. L\'agent evoluciona cada temporada i el reporting avançat tanca renovacions amb dades reals.' },
